typescript_snippet:
// TypeScript usage example
async function* inputGenerator() {
  yield 'q1'; yield 'q2'; yield 'q3';
}
for await (const item of windowedStream(inputGenerator(), { batchSize: 8, maxLatencyMs: 150 })) {
  // item: streamed per-input result
  console.log(item)
}

go_snippet:
// Go usage example (pseudo)
ctx := context.Background()
inputs := []string{"q1","q2","q3","q4"}
it := NewWindowedIterator(ctx, inputs, WithBatchSize(16), WithMaxLatencyMS(120))
for it.Next() {
    res := it.Value() // Value() returns per-item result as soon as available
    fmt.Println(res)
}
if err := it.Err(); err != nil {
    log.Fatalf("iteration failed: %v", err)
}
